from datetime import date, timedelta


def _days_in_month(year: int, month: int) -> int:
    if month == 12:
        return 31
    return (date(year, month + 1, 1) - date(year, month, 1)).days


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = map(int, start.split("-"))
    start_date = date(y, m, d)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])

    results = []
    if kind == "DAILY":
        cur = start_date
        while len(results) < count:
            results.append(cur.isoformat())
            cur += timedelta(days=k)
        return results

    if kind == "WEEKLY":
        weekdays = {code: i for i, code in enumerate(["MO", "TU", "WE", "TH", "FR", "SA", "SU"])}
        wanted = sorted(weekdays[c] for c in parts[3].split(","))
        week0_monday = start_date - timedelta(days=start_date.weekday())
        week_index = 0
        candidates = []
        # enumerate weeks until enough matches
        w = week0_monday
        while len(candidates) < count:
            if week_index % k == 0:
                for wd in wanted:
                    dt = w + timedelta(days=wd)
                    if dt >= start_date:
                        candidates.append(dt)
            w += timedelta(days=7)
            week_index += 1
        candidates.sort()
        return [dt.isoformat() for dt in candidates[:count]]

    if kind == "MONTHLY" and len(parts) == 3:
        day = int(parts[2])
        # month index relative to month of start
        y0, m0 = y, m
        idx = 0
        while True:
            yy = y0 + (m0 - 1 + idx * k) // 12
            mm = (m0 - 1 + idx * k) % 12 + 1
            if day == -1:
                dd = _days_in_month(yy, mm)
            elif day <= _days_in_month(yy, mm):
                dd = day
            else:
                dd = None
            if dd is not None:
                dt = date(yy, mm, dd)
                if dt >= start_date:
                    results.append(dt.isoformat())
                    if len(results) == count:
                        return results
            idx += 1

    if kind == "MONTHLY" and len(parts) == 5:
        n = int(parts[2])
        wd = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"].index(parts[4])
        y0, m0 = y, m
        idx = 0
        while True:
            yy = y0 + (m0 - 1 + idx * k) // 12
            mm = (m0 - 1 + idx * k) % 12 + 1
            first = date(yy, mm, 1)
            first_wd = (wd - first.weekday()) % 7
            if n == -1:
                dim = _days_in_month(yy, mm)
                last = date(yy, mm, dim)
                dd = dim - ((last.weekday() - wd) % 7)
            else:
                dd = 1 + first_wd + 7 * (n - 1)
            if dd <= _days_in_month(yy, mm):
                dt = date(yy, mm, dd)
                if dt >= start_date:
                    results.append(dt.isoformat())
                    if len(results) == count:
                        return results
            idx += 1

    if kind == "YEARLY":
        mm_s, dd_s = parts[2].split("-")
        mm, dd = int(mm_s), int(dd_s)
        idx = 0
        while True:
            yy = y + idx * k
            if idx * k and (yy - y) % k != 0:
                idx += 1
                continue
            try:
                dt = date(yy, mm, dd)
            except ValueError:
                idx += 1
                continue
            if dt >= start_date:
                results.append(dt.isoformat())
                if len(results) == count:
                    return results
            idx += 1
    return results
